#!/usr/bin/env bash
set -euo pipefail

bridge_file="Landmarks/Landmarks/CEF/TungstenCEFBridge.mm"

if awk '
    /^- \(void\)dealloc/ { in_dealloc = 1 }
    in_dealloc && /^}/ { in_dealloc = 0 }
    in_dealloc && /CloseBrowser/ { found = 1 }
    END { exit found ? 0 : 1 }
' "$bridge_file"; then
    echo "TungstenCEFBridge dealloc must not call CloseBrowser; CEF closes asynchronously during view teardown." >&2
    exit 1
fi

echo "CEFTeardownTests passed"

#!/usr/bin/env bash
set -euo pipefail

model_file="Landmarks/Landmarks/Browser/BrowserModel.swift"

if ! awk '
    /func close\(_ tab: BrowserTab\)/ { in_close = 1 }
    in_close && /tabs\.count == 1/ { saw_single_tab_guard = 1 }
    in_close && /tabs\.remove\(at:/ && !saw_single_tab_guard { exit 1 }
    in_close && /^    }$/ { exit 0 }
' "$model_file"; then
    echo "BrowserModel.close must handle the one-tab case before removing the tab, so CEF is not torn down on Cmd-W." >&2
    exit 1
fi

echo "BrowserModelClosePolicyTests passed"

